wStream* Stream_New(BYTE* buffer, size_t size) /* <=== Stream_New */ 
{
	wStream* s;

	if (!buffer && !size)
		return NULL;

	s = malloc(sizeof(wStream));
	if (!s)
		return NULL;

	if (buffer)
		s->buffer = buffer;
	else
		s->buffer = (BYTE*)malloc(size);

	if (!s->buffer)
	{
		free(s);
		return NULL;
	}

	s->pointer = s->buffer;
	s->capacity = size;
	s->length = size;

	s->pool = NULL;
	s->count = 0;
	s->isAllocatedStream = TRUE;
	s->isOwner = TRUE;
	return s;
}

int ntlm_read_ntlm_v2_response(wStream* s, NTLMv2_RESPONSE* response) /* <=== ntlm_read_ntlm_v2_response */ 
